<script setup lang="ts">
import {ref,watch,onUnmounted,computed} from 'vue';import type {Scenario,Result} from '../types';import Worker from '../workers/runout.worker?worker&inline';import {label,red} from '../engine/cards';
const props=defineProps<{scenario:Scenario}>();const rows=ref<{card:number;result:Result|null}[]>([]),busy=ref(false),error=ref('');let worker:InstanceType<typeof Worker>|null=null;const available=computed(()=>[3,4].includes(props.scenario.board.filter(c=>c!==null).length));
function cancel(){worker?.terminate();worker=null;busy.value=false}
watch(()=>JSON.stringify([props.scenario.hole,props.scenario.board,props.scenario.opponents,props.scenario.ranges]),()=>{cancel();rows.value=[];error.value=''});onUnmounted(cancel);
function run(){cancel();rows.value=[];error.value='';try{worker=new Worker();busy.value=true;worker.onmessage=e=>{if(e.data.type==='error'){error.value=e.data.message;cancel()}else{rows.value=e.data.rows;if(e.data.type==='done')cancel()}};worker.onerror=()=>{error.value='分析任务失败，请重试';cancel()};worker.postMessage({hole:[...props.scenario.hole],board:props.scenario.board.filter(c=>c!==null),opponents:props.scenario.opponents,ranges:[...props.scenario.ranges],samples:2000})}catch(e){error.value=(e as Error).message;cancel()}}
</script><template><details v-if="available" class="panel"><summary>下一张牌 · 获胜概率地图</summary><p class="muted">无需输入下注。分别假设下一张公共牌已出现，重新计算最终独赢率、平局率和权益；不是该牌出现概率。小规模场景精确计算，其余每张 2,000 次模拟，适合观察趋势。</p><button class="secondary full" v-if="!busy" @click="run">计算每张可能牌的概率</button><button class="secondary full" v-else @click="cancel">取消分析 · 已完成 {{rows.length}} 张</button><p class="error" v-if="error">{{error}}</p><div class="runout-grid"><div class="runout-cell" v-for="row in rows" :key="row.card"><strong :class="{red:red(row.card)}">{{label(row.card)}}</strong><template v-if="row.result"><span>独赢 {{(row.result.win*100).toFixed(1)}}%</span><small>平局 {{(row.result.tie*100).toFixed(1)}}%</small><small>权益 {{(row.result.equity*100).toFixed(1)}}%</small><small>{{row.result.method==='exact'?'精确':'模拟 · 权益±'+(1.96*row.result.se*100).toFixed(1)+'百分点'}}</small></template><small v-else>与设定范围不兼容</small></div></div><p class="muted">默认随机对手。自定义范围会按新增公共牌过滤、重新归一化；多人仍联合排除冲突。模拟区间仅为单张权益近似区间，不是所有牌同时成立的区间，也不是独赢率误差。请勿把各行简单平均推导总体胜率。</p></details></template>
